{
  "name": "system-spec-harness",
  "version": "0.1.0",
  "description": "カテゴリ×プラットフォームの網羅マトリクス、公式出典、独立完成度評価を用いてシステム仕様書を生成するハーネス plugin。",
  "author": {
    "name": "harness maintainers"
  },
  "hooks": "./hooks/hooks.json"
}

{
  "$schema": "../../harness-creator/skills/ref-pkg-contract/schemas/package-contract.schema.json",
  "package_mode": "bundle",
  "plugin_name": "dev-graph",
  "entry_points": {
    "skills": [
      "run-dev-graph-init",
      "run-dev-graph-node",
      "run-dev-graph-sync",
      "run-dev-graph-requirements",
      "run-dev-graph-render",
      "run-dev-graph-decompose",
      "run-dev-graph-schedule",
      "run-dev-graph-status",
      "run-dev-graph-system-spec",
      "run-skill-feedback"
    ],
    "agents": [
      "dev-graph-integrity-auditor",
      "dev-graph-sync-conflict-verifier",
      "dev-graph-requirements-verifier",
      "dev-graph-parallel-safety-verifier"
    ],
    "commands": [
      "dev-graph"
    ],
    "hooks": [
      "guard-graph-schema",
      "reconcile-task-lifecycle",
      "audit-graph-authority-drift"
    ]
  },
  "distribution": {
    "distributable": false,
    "bundle_targets": [],
    "category": "development-planning",
    "tags": [
      "task-graph",
      "feature-orchestration",
      "worktree"
    ]
  },
  "depends_on": [
    "system-spec-harness",
    "system-dev-planner"
  ],
  "skill_dependencies": {
    "run-dev-graph-decompose": [
      "system-dev-planner"
    ],
    "run-dev-graph-node": [
      "system-dev-planner"
    ],
    "run-dev-graph-requirements": [
      "system-dev-planner"
    ],
    "run-dev-graph-system-spec": [
      "system-spec-harness"
    ]
  },
  "pkg_checks": {}
}

{
  "$schema": "../../harness-creator/skills/ref-pkg-contract/schemas/package-contract.schema.json",
  "package_mode": "bundle",
  "plugin_name": "system-spec-harness",
  "entry_points": {
    "skills": [
      "run-system-spec-elicit",
      "run-system-spec-doc-fetch",
      "run-system-spec-compile",
      "ref-system-design-knowledge",
      "assign-system-spec-completeness-evaluator"
    ],
    "agents": [
      "system-spec-hearing-auditor",
      "system-spec-matrix-auditor",
      "system-spec-doc-freshness-auditor"
    ],
    "commands": [
      "spec-hearing-start",
      "spec-compile"
    ],
    "hooks": [
      "guard-confirmed-chapter-overwrite",
      "record-audit-fork"
    ]
  },
  "distribution": {
    "distributable": true,
    "bundle_targets": [
      "skills-full"
    ],
    "category": "productivity",
    "tags": [
      "spec",
      "hearing",
      "system-design"
    ]
  },
  "depends_on": [],
  "pkg_checks": {}
}

{
  "claude_hooks": {
    "post_tool_reconcile": false,
    "project_plugin_link": ".claude/dev-graph-plugin",
    "session_start": false,
    "source": "plugin",
    "task_completed_gate": false
  },
  "content_roots": {
    "architecture": "architecture",
    "documents": "docs",
    "features": "features",
    "issues": "issues",
    "specifications": "specs",
    "system_spec": "system-spec",
    "tasks": "tasks"
  },
  "execution_tracker": {
    "beads": {
      "board": "none",
      "github_mirror": "none",
      "issue_prefix": "lt",
      "server_mode": false
    },
    "mode": "beads"
  },
  "github": {
    "completion_policy": {
      "closed_unmerged": "keep_active",
      "issue_reopened": "reopen_task",
      "local_reconciliation": [
        "manual_sync"
      ],
      "required_pull_requests": "all",
      "revert": "create_follow_up_unless_issue_reopened",
      "scheduled_reconciliation": {
        "enabled": false,
        "entry_point": "dev-graph sync --reconcile-lifecycle",
        "interval_minutes": 5,
        "owner": "claude_session_start"
      },
      "target_branch": "default",
      "trigger": "linked_pr_merged"
    },
    "enabled": false,
    "issue_repository": "example/dev-graph-live-trial",
    "projects": []
  },
  "local_state": {
    "cache": ".dev-graph/cache",
    "graph": ".dev-graph/state/graph.json",
    "locks": ".dev-graph/locks"
  },
  "path_policy": {
    "allow_outside_repository": false,
    "authority": "caller-repository",
    "follow_content_symlinks_outside_repository": false,
    "stored_paths": "repository-relative"
  },
  "repository_id": "local:sha256:076357c7c6fcf2ac08645b78293fc1626f7b2aa91ce8660f0ee48ffe333d9a69",
  "schema_version": "1.0.0",
  "worktrees": {
    "completion_write_branch": "default",
    "coordination_store": "git_common_dir",
    "dirty_worktree_policy": "fail_closed",
    "enabled": true,
    "heartbeat_seconds": 60,
    "lease_ttl_seconds": 1800
  }
}

